import AppKit
import SwiftUI

/// Shared rounding for the terminal panel chip. The border, dim scrim, and diff clip (PaneTreeView)
/// and the surface's own layer clip (below) must all use the same radius or the corners mismatch —
/// one constant keeps them in lockstep.
enum TerminalPanelMetrics {
  static let cornerRadius: CGFloat = 8
}

/// Hosts a single terminal surface, clipped to rounded corners. Terminals live in
/// `TerminalSessions` (retained across switches); this view mounts whichever one it's given and
/// re-mounts when that changes.
///
/// Occlusion (plan A4): the hosted surface is marked visible on mount and **hidden on dismantle**,
/// so a backgrounded tab's GPU surface stops rendering while it stays alive (its shell keeps running).
/// With splits (issue #3) the model also drives occlusion centrally (`reconcileOcclusion`), so several
/// panes can be visible at once; this view's mount/dismantle is the per-mount backstop.
///
/// This hosts exactly one terminal surface (one tab). A split composes several of these into one
/// on-screen layout via the recursive pane renderer over `PaneLayout` — splitting does not nest
/// surfaces inside a tab.
///
/// Focus (issue #3): with multiple panes mounted, only the focused one may grab first responder.
/// `isFocusedPane` drives that — the host passes `true` for exactly the focused leaf. Mount no longer
/// force-focuses unconditionally (that would let the last-mounted pane steal focus); focus is applied
/// from `isFocusedPane` on update. A pane the user clicks becomes first responder via the surface's own
/// `mouseDown`, which feeds the selection back through `onFocused`.
struct TerminalContainerView: NSViewRepresentable {
  let view: GhosttySurfaceView
  /// Whether this pane should hold keyboard focus. Solo callers leave it `true`; the split renderer
  /// passes `true` only for the focused leaf.
  var isFocusedPane: Bool = true
  /// When a status bar is stacked below the surface (issue #49), the surface rounds only its TOP
  /// corners so the terminal and the bar together read as one rounded panel (the enclosing clip
  /// rounds the bottom). Solo/default keeps all four rounded.
  var roundsBottomCorners: Bool = true

  func makeNSView(context: Context) -> NSView {
    let container = NSView()

    // away while revealed — e.g. the window closing.
    _ = reducer.disable()
    syncPreviewing()
  }
}

private var panel: some View {
  content()
    // Breathing room between the card's top edge and the first row — matches the native pinned
    // card's top inset. Only for the leading sidebar (a List); the trailing inspector's first
    // element is a full-width header bar that sits flush.
    .padding(.top, side == .leading ? 10 : 0)
    .frame(width: width)
    .frame(maxHeight: .infinity)
    // The same floating card the docked column uses (`sidebarCard`). `topMargin: 0` extends the card
    // up to sit flush below the toolbar like the native pinned card (the reveal's safe-area top is
    // ~8pt lower than the native card's top), so pinned and unpinned line up.
    // Both docked columns now use the frosted `.sidebar` vibrancy, so both reveals match them
    // (pinned == unpinned). `elevated`: an unpinned panel floats over the content, so it gets a
    // deeper drop shadow than the docked card.
    .sidebarCard(topMargin: 0, vibrant: true, elevated: true)
    .offset(x: panelOffsetX)
    .opacity(reducer.revealed ? 1 : 0)
    // Hidden/off-screen panel must never eat terminal clicks.
    .allowsHitTesting(reducer.revealed)
    .onHover { hovering in
      // Ignore hover while hidden. `.offset` moves only the rendering, so the hidden panel's hover
      // region still occupies the full-height leading column — without this guard hovering anywhere
      // down the left edge would reveal it (issue #56). Once revealed the panel sits at offset 0, so
      // its hover region matches what's on screen and keeping it open / hiding on exit works.
      guard reducer.revealed else { return }
      apply { $0.setPanelHover(hovering) }
    }
    .onExitCommand { dismiss() }
    // Surface the panel as one addressable accessibility container so it's queryable (by the reveal
    // UI test) while keeping its children reachable; without `.contain` the identifier on this
    // List-wrapping container doesn't surface as an XCUIElement.
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier(
      side == .leading ? "sidebar.reveal.leading" : "sidebar.reveal.trailing"

